-- AVA IPECC: quatro atividades de 15 minutos para cada uma das 40 semanas
create table if not exists public.ava_atividades (
  id uuid primary key default gen_random_uuid(),
  aula_id uuid not null references public.ava_aulas(id) on delete cascade,
  ordem smallint not null check (ordem between 1 and 4),
  tipo text not null check (tipo in ('revisao','exercicio','portfolio','autoavaliacao')),
  titulo text not null,
  instrucoes text not null,
  pergunta text not null,
  duracao_min smallint not null default 15 check (duracao_min = 15),
  publicada boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (aula_id, ordem)
);

create index if not exists ava_atividades_aula_ordem_idx on public.ava_atividades(aula_id, ordem);
alter table public.ava_atividades enable row level security;

drop policy if exists "atividades publicadas para autenticados" on public.ava_atividades;
create policy "atividades publicadas para autenticados" on public.ava_atividades for select to authenticated using (publicada = true or exists (select 1 from public.ava_perfis p where p.id = auth.uid() and p.papel in ('admin','professor','monitor')));

drop policy if exists "gestao de atividades pela equipe" on public.ava_atividades;
create policy "gestao de atividades pela equipe" on public.ava_atividades for all to authenticated using (exists (select 1 from public.ava_perfis p where p.id = auth.uid() and p.papel in ('admin','professor'))) with check (exists (select 1 from public.ava_perfis p where p.id = auth.uid() and p.papel in ('admin','professor')));

on conflict (aula_id, ordem) do update set tipo=excluded.tipo,titulo=excluded.titulo,instrucoes=excluded.instrucoes,pergunta=excluded.pergunta,duracao_min=excluded.duracao_min,publicada=excluded.publicada,updated_at=now();
